"""The question bank for developer mode. Each question keeps its key forever, so editing one here updates it in
place after the next migrate (see services.sync_questions). Python "output" questions are run by the tests to prove
their answers; keep their code to the standard library and printing."""


def q(key, language, level, kind, topic, prompt, choices, answer, explanation, code=""):
    return {"key": key, "language": language, "level": level, "kind": kind, "topic": topic, "prompt": prompt,
            "code": code.strip("\n"), "choices": choices, "answer": answer, "explanation": explanation}


